const [draft, setDraft] = useState("");

const submitDraft = () => {
  onAdd(draft);
  setDraft("");
};

return (
  <div>
    <div className="flex gap-2 mb-4">
      <input
        className="flex-1 rounded bg-slate-900 border border-slate-700 px-3 py-2"
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
        placeholder="What needs doing?"
      />
      <button className="rounded bg-cyan-500 px-4 py-2" onClick={submitDraft}>
        Add
      </button>
    </div>
    <ul className="space-y-2">
      {todos.map((todo) => (
        <li key={todo.id} className="flex items-center justify-between rounded bg-slate-900 px-3 py-2">
          <label className="flex items-center gap-2">
            <input type="checkbox" checked={todo.done} onChange={() => onToggle(todo.id)} />
            <span className={todo.done ? "line-through text-slate-500" : ""}>{todo.text}</span>
          </label>
          <button className="text-slate-400 hover:text-red-400" onClick={() => onRemove(todo.id)}>
            Remove
          </button>
        </li>
      ))}
    </ul>
  </div>
);
